package server

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"io"
)

var dashboardHTML = mustDashboardAsset("")

var dashboardCSS = mustDashboardAsset("")

var dashboardJS = mustDashboardAsset("")

func mustDashboardAsset(encoded string) string {
	raw, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		panic(err)
	}
	reader, err := gzip.NewReader(bytes.NewReader(raw))
	if err != nil {
		panic(err)
	}
	value, err := io.ReadAll(reader)
	if err != nil {
		panic(err)
	}
	if err := reader.Close(); err != nil {
		panic(err)
	}
	return string(value)
}
